	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/tax-registrations/{registration_id}", wrapper.UpdateTaxRegistration)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/tax-registrations/{registration_id}/closure", wrapper.CloseTaxRegistration)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/states", wrapper.ListStates)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/organisation-settings", wrapper.GetOrganisationSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/organisation-settings", wrapper.UpdateOrganisationSettings)
